import sympy as sp
x=sp.symbols('x')
sols=sp.solve(sp.Eq(x/(x**2-2*x+1),sp.Rational(1,3)),x)
vals={sp.nsimplify(sp.simplify(s**3+1/s**3)) for s in sols}
assert vals=={110}
opts={'A':110,'B':180,'C':160,'D':130}
v=vals.pop()
assert v==opts['A']
for k in 'BCD': assert v!=opts[k]

